  const w = { x0, y0, x1, y1, color, hgt: opt.h || 4, kind: opt.kind || 'wall', graf: opt.graf || null };
  bake(x0 - 2, y0 - 8, x1 + 6, y1 + 8, 8, (g) => drawWallBaked(g, w));
