  addBuilding(R.x0 + 30, R.y0 + 140, R.x0 + 120, R.y1 - 200, 34, { style: 'office', roofType: 'flat', roofColor: '#6e7b6a', wall: '#e9d9a8', lit: 0.1 });
  decal(R.x0 + 150, R.y0 + 180, R.x1 - 40, R.y1 - 220, 'court');
