  fenceRect(6380, 1580, 7420, 3800, [{ side: 'E', at: 2400, w: 60 }, { side: 'W', at: 3200, w: 60 }], 'wood');
  scatterTrees(6420, 1620, 7380, 3760, 14, ['mango', 'round', 'round', 'pine'], 1, 1.4);
