  addBuilding(7200, 3500, 7300, 3580, 22, { style: 'shed', roofType: 'gable', roofColor: '#6d5a44', wall: '#9a8466', lit: 0 });
  World.animalsDef.push({ type: 'cow', n: 12, rect: [6420, 1620, 7380, 3760] });
