            for (const [x, y] of P) { g.fillStyle = 'rgba(0,0,0,0.35)'; g.fillRect(x - 1, y, 4, 3); g.fillStyle = '#6a4a2c'; g.fillRect(x - 2, y - 2, 4, 4); g.fillStyle = '#8a6440'; g.fillRect(x - 2, y - 2, 4, 1.4); }
