function finishRace() {
  if (Act.race.racha) { finishRacha(Act.race); return; }
  const R = Act.race, r = R.r, t = R.t;
  Desafios.conta('percurso');
  const medal = t <= r.gold ? 3 : t <= r.silver ? 2 : t <= r.bronze ? 1 : 0;
  const names = ['Sem medalha', 'Bronze', 'Prata', 'Ouro'];
  const rewards = [60, 300, 550, 900];
  const prev = Profile.races[r.id] || { best: Infinity, medal: -1 };
  let v;
  if (medal > prev.medal) v = rewards[medal] - (prev.medal > 0 ? rewards[prev.medal] : 0);
  else v = Math.round(rewards[medal] * 0.15);
  v = Math.max(v, 40);
  const record = t < prev.best, pos = Recordes.posicao(r, t);
  Profile.races[r.id] = { best: Math.min(prev.best, t), medal: Math.max(prev.medal, medal) };
  Act.race = null;
  AudioSys.chime();
  pay(v);
  Resultado.mostra({ titulo: r.name, sub: 'Tempo ' + fmtTime(t) + ' · ' + pos + 'º no placar' + (record ? ' · NOVO RECORDE' : ''), medalha: names[medal], medalhaN: medal, estrelas: null, linhas: [['Prêmio do percurso', v]], total: v });
  saveGame();
}
function abandonActivity() {
  if (Act.race) { Act.race = null; toast('Percurso abandonado', '', 'bad'); return true; }
  if (Act.delivery) { Act.delivery = null; toast('Entrega cancelada', 'O cliente vai ter que esperar…', 'bad'); return true; }
  if (Act.ride) { Act.ride = null; Act.rideT = 8; toast('Corrida cancelada', 'O passageiro chamou outro motorista.', 'bad'); return true; }
  if (Act.waypoint) { Act.waypoint = null; toast('Destino do GPS removido', '', 'info'); return true; }
  return false;
}
function visitShop(s) {
  if (Profile.visited.includes(s.id)) return;
  Profile.visited.push(s.id);
  const total = World.shops.filter((x) => x.kind !== 'garagem').length;
  const n = Profile.visited.length;
  pay(100, 'Caderneta: ' + s.name + ' (' + n + '/' + total + ')');
  if (n === total) setTimeout(() => pay(1500, 'Caderneta completa! Você conhece a cidade inteira.'), 900);
}

/* ---------- GPS (Dijkstra na malha viária) ---------- */
function gpsRoute(sx, sy, tx, ty, hx, hy) {
  const A = nearestEdge(sx, sy), B = nearestEdge(tx, ty);
  if (!A.e || !B.e) return null;
  const pA = A.e.h ? [A.e.a.x + A.s, A.e.a.y] : [A.e.a.x, A.e.a.y + A.s];
  const pB = B.e.h ? [B.e.a.x + B.s, B.e.a.y] : [B.e.a.x, B.e.a.y + B.s];
  if (A.e === B.e) return { pts: [[sx, sy], pA, pB, [tx, ty]], len: Math.abs(A.s - B.s) + A.d + B.d };
  const N = World.nodes.length;
  const dist = new Float64Array(N).fill(Infinity), prev = new Int32Array(N).fill(-1), done = new Uint8Array(N);
  dist[A.e.a.id] = A.s; dist[A.e.b.id] = A.e.len - A.s;
  // (0.2.0) respeita para onde você está indo: voltar para trás custa um retorno (só se precisar mesmo)
  if (hx !== undefined) { const ux = A.e.b.x - A.e.a.x, uy = A.e.b.y - A.e.a.y, pr = (ux * hx + uy * hy) / (Math.hypot(ux, uy) || 1); if (pr > 0.3) dist[A.e.a.id] += 350; else if (pr < -0.3) dist[A.e.b.id] += 350; }
  for (;;) {
    let u = -1, best = Infinity;
    for (let i = 0; i < N; i++) if (!done[i] && dist[i] < best) { best = dist[i]; u = i; }
    if (u < 0) break;
    done[u] = 1;
    const n = World.nodes[u];
    for (const e of n.edges) {
      const o = e.a === n ? e.b : e.a;
      const nd = best + e.len;
      if (nd < dist[o.id]) { dist[o.id] = nd; prev[o.id] = u; }
    }
  }
  const ca = dist[B.e.a.id] + B.s, cb = dist[B.e.b.id] + (B.e.len - B.s);
  let end = ca <= cb ? B.e.a : B.e.b;
  const len = Math.min(ca, cb) + A.d + B.d;
  if (!isFinite(len)) return null;
  const path = [];
  for (let i = end.id; i >= 0; i = prev[i]) path.push(World.nodes[i]);
  path.reverse();
  const pts = [[sx, sy], pA];
  for (const n of path) pts.push([n.x, n.y]);
  pts.push(pB, [tx, ty]);
  return { pts, len };
}
/* ---------- Nav: caminho pelas ruas para quem dirige (GPS, caminhão do Seu Zé e as próximas IAs, como a polícia) ----------
   Usa a mesma malha de ruas do GPS (cruzamentos ligados pelas ruas), mas monta a linha por onde um carro anda de verdade:
   na mão certa (faixa da direita de cada rua), com curva arredondada nos cruzamentos e, se pedir, sem as retas de fora da rua. */
// (0.2.0) rota de cruzamentos para um carro do trânsito com destino (Seu Zé, e no futuro a polícia):
// sai do cruzamento 'inicio' e chega na rua 'alvoE' (no ponto alvoS a partir de alvoE.a). Voltar pela rua de onde
// veio ('evita') custa um retorno: só faz se precisar mesmo. Devolve os cruzamentos e o sentido na rua final.
function navNos(inicio, evita, alvoE, alvoS) {
  const N = World.nodes.length, dist = new Float64Array(N).fill(Infinity), prev = new Int32Array(N).fill(-1), done = new Uint8Array(N);
  dist[inicio.id] = 0;
  for (;;) {
    let u = -1, best = Infinity;
    for (let i = 0; i < N; i++) if (!done[i] && dist[i] < best) { best = dist[i]; u = i; }
    if (u < 0) break;
    done[u] = 1;
    const n = World.nodes[u];
    for (const e of n.edges) {
      if (e.closed) continue;
      const o = e.a === n ? e.b : e.a, nd = best + e.len + (n === inicio && e === evita ? 400 : 0);
      if (nd < dist[o.id]) { dist[o.id] = nd; prev[o.id] = u; }
    }
  }
  const ca = dist[alvoE.a.id] + alvoS, cb = dist[alvoE.b.id] + (alvoE.len - alvoS);
  if (!isFinite(Math.min(ca, cb))) return null;
  const fim = ca <= cb ? alvoE.a : alvoE.b, nos = [];
  for (let i = fim.id; i >= 0; i = prev[i]) nos.push(World.nodes[i]);
  nos.reverse();
  return { nos, dirFinal: fim === alvoE.a ? 1 : -1 };
}
function navArestaEntre(a, b) { for (const e of a.edges) if ((e.a === a && e.b === b) || (e.b === a && e.a === b)) return e; return null; }
function navRota(sx, sy, tx, ty, opt) {
  opt = opt || {};
  const r = gpsRoute(sx, sy, tx, ty, opt.hx, opt.hy); if (!r) return null;
  let P = r.pts.slice(1, -1); // só a parte que está na rua (pA, cruzamentos, pB)
  if (P.length < 2) return { pts: r.pts, len: r.len };
  // faixa de cada trecho (mão direita): pega a rua entre os dois pontos; nas pontas usa a rua mais perto
  const faixaDe = (a, b) => {
    const na = World.nodes.find((n) => n.x === a[0] && n.y === a[1]), nb = World.nodes.find((n) => n.x === b[0] && n.y === b[1]);
    const e = na && nb ? navArestaEntre(na, nb) : nearestEdge((a[0] + b[0]) / 2, (a[1] + b[1]) / 2).e;
    return e ? (e.T.lanes ? e.T.lanes[0] : e.hw * 0.4) : 20;
  };
  const segs = [];
  for (let i = 0; i < P.length - 1; i++) {
    const a = P[i], b = P[i + 1], L = Math.hypot(b[0] - a[0], b[1] - a[1]); if (L < 0.5) continue;
    const ux = (b[0] - a[0]) / L, uy = (b[1] - a[1]) / L, off = opt.centro ? 0 : faixaDe(a, b);
    segs.push({ ax: a[0] - uy * off, ay: a[1] + ux * off, bx: b[0] - uy * off, by: b[1] + ux * off, ux, uy, L });
  }
  if (!segs.length) return { pts: r.pts, len: r.len };
  const out = [[segs[0].ax, segs[0].ay]];
  for (let i = 0; i < segs.length; i++) {
    const S = segs[i], N = segs[i + 1];
    if (!N) { out.push([S.bx, S.by]); break; }
    const giro = S.ux * N.uy - S.uy * N.ux, reto = S.ux * N.ux + S.uy * N.uy;
    if (Math.abs(giro) < 0.2 && reto > 0) { out.push([S.bx, S.by]); continue; } // segue reto
    // curva arredondada: encontro das duas faixas e um arco por dentro do cruzamento (retorno vira um "U")
    const R = Math.min(32, S.L / 2, N.L / 2);
    // ponto de encontro das duas linhas (ruas são retas em x ou y)
    const ix = Math.abs(S.ux) > 0.5 ? N.ax : S.bx, iy = Math.abs(S.ux) > 0.5 ? S.by : N.ay;
    const p0 = [ix - S.ux * R, iy - S.uy * R], p2 = [ix + N.ux * R, iy + N.uy * R];
    if (reto < -0.5) { out.push([S.bx, S.by], [N.ax, N.ay]); continue; }
    out.push(p0);
    for (let k = 1; k < 6; k++) { const t = k / 6, u = 1 - t; out.push([u * u * p0[0] + 2 * u * t * ix + t * t * p2[0], u * u * p0[1] + 2 * u * t * iy + t * t * p2[1]]); }
    out.push(p2);
  }
  const pts = opt.soRua ? out : [[sx, sy], ...out, [tx, ty]];
  return { pts, len: r.len, rua: out };
}
function currentTarget() {
  if (Act.race) { const R = Act.race; const p = R.idx < R.r.pts.length ? R.r.pts[R.idx] : null; return p ? { x: p[0], y: p[1], kind: 'race' } : null; }
  if (Act.delivery) { const D = Act.delivery, q = D.stage === 'pickup' ? D.pick : D.dest; return { x: q.x, y: q.y, kind: 'delivery' }; }
  if (Act.ride) { const q = Act.ride.stage === 'pickup' ? Act.ride.pick : Act.ride.dest; return { x: q.x, y: q.y, kind: 'ride' }; }
  const et = Events.gpsTarget();
  if (et && Events.cur.stage !== 'wait') return et;
  if (Act.waypoint) return { x: Act.waypoint.x, y: Act.waypoint.y, kind: 'waypoint' };
  return et;
}
function nearestShop(kind) {
  let best = null, bd = Infinity;
  for (const s of World.shops) if (s.kind === kind) { const d = Math.hypot(s.x - player.x, s.y - player.y); if (d < bd) { bd = d; best = s; } }
  return best;
}

/* ---------- atualização por quadro ---------- */
function updateActivities(dt) {
  const p = player, sp = p.speed;
  updateJobs(dt);
  // pontos de interesse
  for (const poi of World.pois) {
    if (Profile.discovered.includes(poi.id)) continue;
    if (Math.hypot(poi.x - p.x, poi.y - p.y) < poi.r) {
      Profile.discovered.push(poi.id);
      AudioSys.chime();
      toast('Ponto de interesse: ' + poi.name, poi.desc, 'info');
      pay(150);
      if (Profile.discovered.length === World.pois.length) setTimeout(() => pay(2000, 'Todos os pontos de interesse descobertos!'), 1200);
    }
  }
  // radares (pardal)
  for (const r of World.radars) {
    if (r.obj.down !== undefined) continue;
    if (p.x < r.x0 || p.x > r.x1 || p.y < r.y0 || p.y > r.y1) continue;
    const kmh = sp * 0.3;
    if (kmh > r.lim + 3 && Game.time - r.obj.last > 6) {
      r.obj.last = Game.time; Cam.flash = 1;
      AudioSys.tone(2400, 0.06, 'square', 0.06, 'ui'); AudioSys.tone(2400, 0.06, 'square', 0.06, 'ui', null, 0.1);
      const fine = Math.min(130, Math.max(0, Math.floor(Profile.money)));
      if (fine > 0) pay(-fine, 'Pardal! ' + Math.round(kmh) + ' km/h numa via de ' + r.lim);
      else toast('Pardal!', 'Flagrado a ' + Math.round(kmh) + ' km/h. A multa vai chegar pelo correio…', 'bad');
    }
  }
  // entrega em andamento
  if (Act.delivery) {
    const d = Act.delivery;
    d.t += dt;
    if (d.stage !== 'pickup' && Math.hypot(d.dest.x - p.x, d.dest.y - p.y) < 70 && sp < 40) finishDelivery();
  }
  // corrida
  if (Act.race) {
    const R = Act.race;
    if (R.count > 0) {
      R.count -= dt;
      const c = Math.ceil(R.count);
      if (c < R.lastBeep && c >= 1) { AudioSys.beep(false); R.lastBeep = c; }
      if (R.count <= 0) { AudioSys.beep(true); R.lastBeep = 0; }
    } else {
      R.t += dt;
      const cp = R.r.pts[R.idx];
      if (Math.hypot(cp[0] - p.x, cp[1] - p.y) < 95) {
        R.idx++;
        if (R.idx >= R.r.pts.length) finishRace(); else { AudioSys.checkpoint(); Act.gpsT = 0; }
      } else if (distToSeg(p.x, p.y, R.idx ? R.r.pts[R.idx - 1] : R.r.start, cp) > 1200) { // longe do trajeto (não do ponto: o racha da Cara-Pintada tem 4 km de reta)
        Act.race = null; toast('Percurso cancelado', 'Você se afastou demais do trajeto.', 'bad');
      }
    }
  }
  // GPS
  const tgt = currentTarget();
  if (Act.waypoint && Math.hypot(Act.waypoint.x - p.x, Act.waypoint.y - p.y) < 90) { Act.waypoint = null; toast('Você chegou ao destino', '', 'good'); AudioSys.checkpoint(); }
  Act.gpsT -= dt;
  if (tgt && (Act.gpsT <= 0 || !Act.gps)) { const sp = Math.hypot(p.vx, p.vy); Act.gps = navRota(p.x, p.y, tgt.x, tgt.y, sp > 40 ? { hx: p.vx / sp, hy: p.vy / sp } : {}); Act.gpsT = 0.8; Act.gpsTarget = tgt; } // rota pela faixa, com curvas e no sentido em que você vai
  if (!tgt) { Act.gps = null; Act.gpsTarget = null; }
  // vagas
  Act.parkSpot = null;
  if (!Act.race) {
    let best = null, bd = 520;
    for (const s of World.parkSpots) { const d = Math.hypot(s.x - p.x, s.y - p.y); if (d < bd) { bd = d; best = s; } }
    Act.parkSpot = best;
    if (best) {
      const inside = parkedIn(best);
      if (Act.parkLock === best.id) { Act.parkHold = 0; if (!inside) Act.parkLock = null; }
      else if (inside && sp < 12) {
        Act.parkHold += dt;
        if (Act.parkHold >= 1.2) {
          Act.parkHold = 0; Act.parkLock = best.id;
          const cd = Act.parkCd[best.id] || -1e9;
          const rev = Math.abs(angDiff(p.a, best.a)) > Math.PI / 2;
          if (Game.time - cd < 120) toast('Vaga ocupada há pouco', 'Tente outra vaga ou volte mais tarde.', 'info');
          else {
            const first = !Profile.parks[best.id];
            Profile.parks[best.id] = true; Act.parkCd[best.id] = Game.time;
            const v = (first ? best.reward : 45) * (rev ? 1.3 : 1);
            pay(v, (rev ? 'Baliza de ré perfeita! ' : 'Estacionou bonito! ') + best.name);
          }
        }
      } else Act.parkHold = 0;
    }
  }
  // interações (E)
  Act.prompt = null;
  if (sp < 70 && !(Act.race && Act.race.count <= 0)) {
    let best = null, bd = Infinity;
    for (const s of World.shops) {
      const d = Math.hypot(s.x - p.x, s.y - p.y);
      if (d < (s.radius || 72) && d < bd) { bd = d; best = s; }
    }
    if (best && !lojaAberta(best)) Act.prompt = { text: 'Fechada agora — ' + best.name, act: () => avisoFechada(best) }; // fora do horário: só o aviso "Loja fechada"
    else if (best) {
      const verb = { garagem: 'Entrar na garagem', posto: 'Abastecer / lavar — ' + best.name, oficina: 'Oficina — consertar e melhorar' }[best.kind];
      Act.prompt = { text: verb || (best.pickup && !Act.delivery ? 'Pegar entrega — ' + best.name : 'Entrar — ' + best.name), act: () => openShopDialog(best) };
    } else if (!Act.race) {
      if (rachaOpen()) for (const r of World.rachas) {
        if (Math.hypot(r.start[0] - p.x, r.start[1] - p.y) < 85) { Act.prompt = { text: 'Racha (ilegal): ' + r.name + ' — aposta R$ ' + fmtMoney(r.bet) + ' contra ' + r.rival, act: () => startRacha(r) }; break; }
      }
      if (!Act.prompt) for (const r of World.races) {
        if (Math.hypot(r.start[0] - p.x, r.start[1] - p.y) < 85) {
          const rec = Profile.races[r.id];
          Act.prompt = { text: 'Iniciar percurso: ' + r.name + (rec ? ' (recorde ' + fmtTime(rec.best) + ')' : ''), act: () => startRace(r) };
          break;
        }
      }
    }
  }
  // dicas do modo livre
  Act.hintT -= dt;
  if (Act.hintT <= 0) { Act.hintT = 11; Act.hintI++; }
}
function parkedIn(s) {
  const p = player, m = p.m;
  let da = Math.abs(angDiff(p.a, s.a));
  if (da > Math.PI / 2) da = Math.PI - da;
  if (da > 0.22) return false;
  const c = Math.cos(s.a), sn = Math.sin(s.a);
  const pc = Math.cos(p.a), ps = Math.sin(p.a);
  for (const [u, v] of [[m.L / 2, m.W / 2], [m.L / 2, -m.W / 2], [-m.L / 2, m.W / 2], [-m.L / 2, -m.W / 2]]) {
    const wx = p.x + pc * u - ps * v - s.x, wy = p.y + ps * u + pc * v - s.y;
    const lu = wx * c + wy * sn, lv = -wx * sn + wy * c;
    if (Math.abs(lu) > s.l / 2 + 3 || Math.abs(lv) > s.w / 2 + 3) return false;
  }
  return true;
}
function freeRoamHint() {
  const disc = Profile.discovered.length, totP = World.pois.length;
  const vis = Profile.visited.length, totV = World.shops.filter((x) => x.kind !== 'garagem').length;
  if (Profile.fuel < 22) { const s = nearestShop('posto'); return ['Combustível baixo', 'Procure um posto: ' + (s ? s.name : '') + '. Marque no mapa do celular (Q).']; }
  if (Profile.damage > 55) return ['Carro avariado', 'Passe na Oficina do Seu Zé, no Distrito da Gambiarra.'];
  const cheapest = CARS.filter((c) => !Profile.owned[c.id]).sort((a, b) => a.price - b.price)[0];
  const list = [
    ['Exploração livre', 'Comércios com marcador amarelo oferecem entregas. Pare em frente e aperte E.'],
    ['Exploração livre', 'Pontos de interesse descobertos: ' + disc + '/' + totP + '. O mapa do celular (Q) mostra o que falta perto de você.'],
    ['Exploração livre', 'Percursos cronometrados começam nas bandeiras azuis. Medalha de ouro paga bem.'],
    ['Exploração livre', 'Caderneta de visitas: ' + vis + '/' + totV + ' estabelecimentos. Cada visita nova rende R$ 100.'],
    ['Exploração livre', 'Vagas marcadas em azul pagam por um estacionamento perfeito. De ré vale mais.'],
    ['Exploração livre', 'Abra o mapa no celular (Q) e clique para traçar uma rota no GPS até qualquer lugar.'],
    ['Exploração livre', 'Cuidado com o pardal: radares nas avenidas (80 km/h) e na BR-101 (110 km/h) multam na hora.'],
    ['Exploração livre', 'Tem churrasquinho na esquina do boteco e forró tocando. São Gambiarra nunca dorme.'],
    ['Cuide do carro', 'Pneus, óleo e bateria gastam. Troque na oficina, no posto (óleo) ou na borracharia (pneus).'],
    ['Farol (' + nomeTecla(tecla('farol')) + ')', 'Parado por muito tempo com o farol aceso, a bateria arria. Aperte ' + nomeTecla(tecla('farol')) + ' para desligar.'],
  ];
  if (cheapest && Profile.money >= cheapest.price) list.push(['Carro novo disponível', 'Você já pode comprar o ' + cheapest.name + ' na sua garagem.']);
  // sem dica de coisa que a história ainda não liberou
  const L2 = list;
  return L2[Act.hintI % L2.length];
}

/* ============================ POLÍCIA: CRIMES, PERSEGUIÇÃO, PRISÃO E FUGA ============================ */
// sistema de perseguição DESLIGADO por enquanto (a pedido): troque para true para reativar
const POLICE_ENABLED = false;
const Police = { heat: 0, level: 0, units: [], spawnT: 0, lostT: 0, bustT: 0, seenT: 0, lastSeen: null, crimeCd: 0, sirenK: 0 };
Police.patrolNear = function (x, y, r) {
  for (const c of Traffic.cars) if (c.model === 'police' && Math.hypot(c.x - x, c.y - y) < r) return c;
  for (const u of this.units) if (Math.hypot(u.x - x, u.y - y) < r) return u;
  return null;
};
// a polícia só age se viu (viatura perto) — ou se o crime foi contra ela
Police.crime = function (why, lvl, x, y, direct) {
  if (!POLICE_ENABLED) return;
  if (Game.mode !== 'play' || !player) return;
  if (!direct && !this.patrolNear(x, y, 460)) return;
  if (this.crimeCd > 0 && lvl <= this.level) return;
  this.crimeCd = 2;
  const before = this.level;
  // bater na polícia durante a perseguição sobe uma estrela; outros crimes só renovam a perseguição
  this.level = Math.min(3, this.level >= lvl ? (direct && this.level > 0 ? this.level + 1 : this.level) : lvl);
  this.lostT = 0; this.seenT = 0; this.lastSeen = { x: player.x, y: player.y };
  if (this.level > before) {
    toast(this.level === 1 ? 'A polícia te viu!' : 'Perseguição aumentou!', why + ' · ' + '★'.repeat(this.level) + ' · fuja ou pare o carro', 'bad');
    AudioSys.siren();
  }
};
function makeUnit(x, y, a) {
  const m = VMODELS.police, r = m.W / 2, span = m.L / 2 - r;
  return { m, x, y, a, v: 0, pts: null, ri: 1, rt: 0, mode: 'route', id: Math.random(), stuckT: 0, isUnit: true, mass: 1.8, circles: [-span, 0, span], hitT: 0,
    hit(imp, nx, ny) { this.v *= 0.45; this.x += nx * Math.min(8, imp * 0.02); this.y += ny * Math.min(8, imp * 0.02); this.hitT = Math.min(1.2, 0.3 + imp / 400); } };
}
Police.spawnUnit = function () {
  const p = player, v = Cam.view;
  let sx, sy;
  const B = World.shops.find((s) => s.kind === 'batalhao');
  if (B && Math.hypot(B.x - p.x, B.y - p.y) < 1600 && !(B.x > v.x0 && B.x < v.x1 && B.y > v.y0 && B.y < v.y1)) { sx = B.x; sy = B.y; }
  else {
    for (let t = 0; t < 12; t++) {
      const a = rnd(TAU), d = rnd(900, 1300);
      const ne = nearestEdge(clamp(p.x + Math.cos(a) * d, 100, WORLD_W - 100), clamp(p.y + Math.sin(a) * d, 100, WORLD_H - 100));
      if (!ne.e || ne.e.T.id === 'dirt' && chance(0.5)) continue;
      const x = ne.e.h ? ne.e.a.x + ne.s : ne.e.a.x, y = ne.e.h ? ne.e.a.y : ne.e.a.y + ne.s;
      if (x > v.x0 - 60 && x < v.x1 + 60 && y > v.y0 - 60 && y < v.y1 + 60) continue;
      sx = x; sy = y; break;
    }
  }
  if (sx === undefined) return;
  this.units.push(makeUnit(sx, sy, Math.atan2(p.y - sy, p.x - sx)));
};
function edgePt(e, s) { return e.h ? [e.a.x + s, e.a.y] : [e.a.x, e.a.y + s]; }
Police.route = function (u, tx, ty) {
  const ne = nearestEdge(u.x, u.y), e = ne.e;
  const fwd = Math.cos(u.a) * e.dx + Math.sin(u.a) * e.dy >= 0, node = fwd ? e.b : e.a;
  const T = nearestEdge(tx, ty);
  let pts;
  if (T.e === e && (fwd ? T.s >= ne.s : T.s <= ne.s)) pts = [[u.x, u.y], edgePt(e, ne.s), edgePt(e, T.s), [tx, ty]];
  else { const r = gpsRoute(node.x, node.y, tx, ty); pts = [[u.x, u.y], edgePt(e, ne.s), [node.x, node.y]].concat(r ? r.pts.slice(1) : [[tx, ty]]); }
  pts = laneShift(pts, 14); if (pts.length > 2) pts.pop();
  return pts;
};
// caminho livre (sem prédio, muro, árvore ou poste) entre dois pontos
function lineClearFor(x0, y0, x1, y1) {
  const n = Math.max(2, Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 25));
  for (let i = 1; i <= n; i++) { const x = x0 + (x1 - x0) * i / n, y = y0 + (y1 - y0) * i / n; if (areaBlocked(x - 9, y - 9, x + 9, y + 9)) return false; }
  return true;
}
Police.unitDrive = function (u, dt) {
  const p = player, d = Math.hypot(p.x - u.x, p.y - u.y);
  // velocidade 70% menor que antes: a viatura é perigosa se você parar ou bater, mas dá para fugir
  this.pace = lerp(this.pace || p.speed, p.speed, 1 - Math.exp(-1.0 * dt));
  const pmax = Math.max(300, p.st.max);
  const capK = [0, 0.9, 0.98, 1.05][this.level] || 0.9;
  const vmax = Math.max(344, Math.min(pmax * capK, this.pace * 1.12 + 55) * 0.94); // 0,672 + 40%
  // rota pelas ruas, na mão direita; recalcula com calma (não copia cada virada sua)
  u.rt -= dt;
  const tgt = this.lostT > 0 && this.lastSeen ? this.lastSeen : p;
  if (!u.pts || u.rt <= 0 || u.ri >= u.pts.length) { u.rt = 2.5; u.pts = Police.route(u, tgt.x, tgt.y); u.ri = 1; }
  // pula pontos da rota que já ficaram para trás (nunca dá ré para buscar um ponto)
  while (u.ri < u.pts.length - 1) { const P = u.pts[u.ri], Q = u.pts[u.ri + 1]; if ((Q[0] - P[0]) * (u.x - P[0]) + (Q[1] - P[1]) * (u.y - P[1]) > 0 || Math.hypot(P[0] - u.x, P[1] - u.y) < 10) u.ri++; else break; }
  // freia antes da esquina
  let cornerV = 1e9;
  if (u.ri < u.pts.length - 1) {
    const A = u.ri > 0 ? u.pts[u.ri - 1] : [u.x, u.y], B = u.pts[u.ri], C = u.pts[u.ri + 1];
    const turn = Math.abs(angDiff(Math.atan2(B[1] - A[1], B[0] - A[0]), Math.atan2(C[1] - B[1], C[0] - B[0])));
    const dB = Math.hypot(B[0] - u.x, B[1] - u.y);
    if (turn > 0.3 && dB < 40 + u.v * 0.8) cornerV = 45 + (1 - turn / Math.PI) * 90 + dB * 0.6;
  }
  // cerco: perto de você e com caminho livre, sai da rota e fecha seu carro
  // (a 1ª viatura atravessa na sua frente, a 2ª encosta atrás, a 3ª fecha o lado)
  const role = this.units.indexOf(u) % 3, ca = Math.cos(p.a), sa = Math.sin(p.a);
  const bp = role === 0 ? [p.x + ca * (48 + p.speed * 0.25), p.y + sa * (48 + p.speed * 0.25)] : role === 1 ? [p.x - ca * 48, p.y - sa * 48] : [p.x - sa * 30, p.y + ca * 30];
  u.block = d < 180 && lineClearFor(u.x, u.y, bp[0], bp[1]);
  let target = Math.min(vmax, cornerV);
  if (!u.block) {
    if (d < 160) target = Math.min(target, p.speed + 20 + d * 0.1);
    if (d < 70) target = Math.min(target, p.speed + 6);
  } else target = Math.min(vmax, Math.hypot(bp[0] - u.x, bp[1] - u.y) * 3 + p.speed * 0.9);
  // não encosta na traseira da outra viatura
  for (const o of this.units) {
    if (o === u) continue;
    const rx = o.x - u.x, ry = o.y - u.y, f = rx * Math.cos(u.a) + ry * Math.sin(u.a);
    if (f > 0 && f < 75 && Math.abs(-rx * Math.sin(u.a) + ry * Math.cos(u.a)) < 26) target = Math.min(target, Math.max(0, o.v - 10 + (f - 55)));
  }
  if (u.hitT > 0) { u.hitT -= dt; target = Math.min(target, 40); }
  u.v += clamp(target - u.v, -420 * dt, 220 * dt);
  // anda exatamente pela rota (como os outros carros), com o volante suave
  let step = Math.max(0, u.v) * dt;
  const ox = u.x, oy = u.y;
  if (u.block) {
    // manobra de cerco: vai até o ponto de bloqueio e, chegando, fica atravessada
    const dx = bp[0] - u.x, dy = bp[1] - u.y, dd = Math.hypot(dx, dy);
    if (dd > 3) { const m = Math.min(dd, step); u.x += dx / dd * m; u.y += dy / dd * m; }
    step = 0; u.rt = 0;
  }
  while (step > 0 && u.ri < u.pts.length) {
    const q = u.pts[u.ri], dx = q[0] - u.x, dy = q[1] - u.y, dd = Math.hypot(dx, dy);
    if (dd < 0.5) { u.ri++; continue; }
    const m = Math.min(dd, step); u.x += dx / dd * m; u.y += dy / dd * m; step -= m;
    if (m >= dd) u.ri++;
  }
  // fim da rota e você bem perto: vai encostar devagar
  if (!u.block && u.ri >= u.pts.length && d < 120 && d > 40 && lineClearFor(u.x, u.y, p.x, p.y)) { const m = Math.min(d - 40, u.v * dt); u.x += (p.x - u.x) / d * m; u.y += (p.y - u.y) / d * m; }
  // nunca entra em prédio, muro ou poste: se for entrar, volta e recalcula
  const bodyHit = [-17, 0, 17].some((k) => { const x = u.x + Math.cos(u.a) * k, y = u.y + Math.sin(u.a) * k; return areaBlocked(x - 7, y - 7, x + 7, y + 7); });
  if (bodyHit && !areaBlocked(ox - 7, oy - 7, ox + 7, oy + 7)) { u.x = ox; u.y = oy; u.v *= 0.5; u.rt = 0; u.stuckT += dt; } else u.stuckT = Math.max(0, u.stuckT - dt);
  if (u.stuckT > 2.5) { const ne = nearestEdge(u.x, u.y), q = edgePt(ne.e, ne.s); u.x = q[0]; u.y = q[1]; u.stuckT = 0; u.pts = null; }
  const mvx = u.x - ox, mvy = u.y - oy;
  const near = Math.hypot(bp[0] - u.x, bp[1] - u.y) < 14;
  if (u.block && near && role === 0) u.a += clamp(angDiff(u.a, p.a + Math.PI / 2), -4 * dt, 4 * dt); // atravessada na sua frente
  else if (mvx * mvx + mvy * mvy > 0.0004) u.a += clamp(angDiff(u.a, Math.atan2(mvy, mvx)), -5 * dt, 5 * dt);
  // trânsito abre caminho para a sirene
  for (const c of Traffic.cars) {
    const rx = c.x - u.x, ry = c.y - u.y, f = rx * Math.cos(u.a) + ry * Math.sin(u.a);
    if (f > 0 && f < 260 && Math.abs(-rx * Math.sin(u.a) + ry * Math.cos(u.a)) < 40) c.yieldT = 1.2;
  }
  // bate nos carros do trânsito como um carro de verdade: empurra e perde velocidade, não atravessa
  for (const c of Traffic.cars) {
    const dx0 = c.x - u.x, dy0 = c.y - u.y; if (dx0 * dx0 + dy0 * dy0 > 90 * 90) continue;
    const uc = Math.cos(u.a), us2 = Math.sin(u.a), cc = Math.cos(c.a), cs = Math.sin(c.a), R = u.m.W / 2 + c.m.W / 2;
    for (const ka of u.circles) for (const kb of c.circles) {
      const ax = u.x + uc * ka, ay = u.y + us2 * ka, bx = c.x + cc * kb, by = c.y + cs * kb, dx = bx - ax, dy = by - ay, dd = Math.hypot(dx, dy);
      if (dd >= R || dd < 0.01) continue;
      const pen = R - dd, nx = dx / dd, ny = dy / dd;
      c.ox += nx * pen * 0.6; c.oy += ny * pen * 0.6; u.x -= nx * pen * 0.4; u.y -= ny * pen * 0.4;
      const rel = (uc * u.v - Math.cos(c.a) * c.v) * nx + (us2 * u.v - Math.sin(c.a) * c.v) * ny;
      if (rel > 50) { c.hit(rel, nx, ny); u.v *= 0.7; }
    }
  }
};
Police.update = function (dt) {
  const p = player; if (!p) return;
  if (!POLICE_ENABLED) { if (this.level || this.units.length) { this.level = 0; this.units.length = 0; } if (this.sirenK > 0.001) { this.sirenK = 0; AudioSys.sirenSet && AudioSys.sirenSet(0, 0, 1); } return; }
  this.crimeCd -= dt;
  // excesso de velocidade na frente de uma viatura de ronda
  const kmh = p.speed * 0.3, lim = regionKeyAt(p.x, p.y) === 'rodovia' ? 110 : 80;
  if (kmh > lim + 35 && this.level === 0) { const pc = this.patrolNear(p.x, p.y, 320); if (pc) this.crime('Excesso de velocidade: ' + Math.round(kmh) + ' km/h', 1, p.x, p.y, true); }
  if (this.level === 0) { if (this.units.length) this.units.length = 0; this.sirenK = lerp(this.sirenK, 0, 1 - Math.exp(-2 * dt)); AudioSys.sirenSet && AudioSys.sirenSet(this.sirenK, 0, 1); return; }
  // reforço conforme o nível
  const want = this.level;
  this.spawnT -= dt;
  if (this.units.length < want && this.spawnT <= 0) { this.spawnT = 4; this.spawnUnit(); }
  for (const u of this.units) this.unitDrive(u, dt);
  // uma viatura nunca entra dentro da outra
  for (let i = 0; i < this.units.length; i++) for (let j = i + 1; j < this.units.length; j++) {
    const A = this.units[i], B = this.units[j];
    for (const ka of [-12, 0, 12]) for (const kb of [-12, 0, 12]) {
      const ax = A.x + Math.cos(A.a) * ka, ay = A.y + Math.sin(A.a) * ka, bx = B.x + Math.cos(B.a) * kb, by = B.y + Math.sin(B.a) * kb;
      const dx = bx - ax, dy = by - ay, dd = Math.hypot(dx, dy), R = 23;
      if (dd >= R || dd < 0.01) continue;
      const push = (R - dd) / 2; B.x += dx / dd * push; B.y += dy / dd * push; A.x -= dx / dd * push; A.y -= dy / dd * push;
    }
  }
  // alguém está te vendo?
  let nearest = 1e9, nu = null;
  for (const u of this.units) { const d = Math.hypot(u.x - p.x, u.y - p.y); if (d < nearest) { nearest = d; nu = u; } }
  const seen = nearest < 650;
  if (seen) { this.lostT = 0; this.lastSeen = { x: p.x, y: p.y }; } else this.lostT += dt;
  // fuga: some da vista por um tempo e as estrelas vão caindo
  const need = 7 + this.level * 3;
  if (this.lostT > need) {
    this.level--; this.lostT = 0;
    if (this.level <= 0) {
      this.level = 0; Profile.escapes = (Profile.escapes || 0) + 1;
      toast('Despistou a polícia!', 'As viaturas voltaram para a ronda.', 'good'); AudioSys.chime();
      this.units.length = 0;
    } else { toast('Perdendo você de vista…', '★'.repeat(this.level) + ' · continue sumido', 'info'); if (this.units.length > this.level) this.units.length = this.level; }
  }
  // prisão: parado (ou quase) com a viatura colada
  const boxed = this.units.filter((u) => Math.hypot(u.x - p.x, u.y - p.y) < 100).length;
  if (nearest < 95 && p.speed < 45) this.bustT += dt * (boxed >= 2 ? 1.5 : 1); else this.bustT = Math.max(0, this.bustT - dt * 2);
  if (this.bustT > 2.6) this.bust();
  // sirene com efeito de aproximação (Doppler)
  if (nu) {
    const dx = p.x - nu.x, dy = p.y - nu.y, dd = Math.hypot(dx, dy) || 1;
    const vrel = ((Math.cos(nu.a) * nu.v - p.vx) * dx + (Math.sin(nu.a) * nu.v - p.vy) * dy) / dd; // >0 aproximando
    this.sirenK = lerp(this.sirenK, clamp(1 - nearest / 1400, 0.05, 1), 1 - Math.exp(-4 * dt));
    AudioSys.sirenSet && AudioSys.sirenSet(this.sirenK, clamp((nu.x - p.x) / 500, -0.9, 0.9), clamp(1 + vrel / 1500, 0.8, 1.25));
  }
};
Police.bust = function () {
  const lvl = this.level, fine = 150 * lvl, tow = 150;
  const total = Math.min(Math.max(0, Math.floor(Profile.money)), fine + tow);
  Profile.busts = (Profile.busts || 0) + 1;
  this.level = 0; this.units.length = 0; this.bustT = 0; this.lostT = 0;
  if (total > 0) pay(-total, null);
  Act.race = null;
  // carro vai para o pátio do Batalhão
  const B = World.shops.find((s) => s.kind === 'batalhao') || World.batalhao;
  if (B) { const ne = nearestEdge(B.x, B.y); player.place(B.x, B.y, ne.e && ne.e.h ? 0 : Math.PI / 2); player.vx = player.vy = 0; Cam.x = B.x; Cam.y = B.y; Traffic.fill(B.x, B.y); }
  Cam.flash = 0.8; AudioSys.error();
  showDialog({ kind: 'POLÍCIA MILITAR', title: 'Você foi detido', text: 'Multa de R$ ' + fmtMoney(fine) + ' (' + '★'.repeat(lvl) + ') e R$ ' + fmtMoney(tow) + ' do guincho. Pago: R$ ' + fmtMoney(total) + '. Seu carro foi levado para o pátio do Batalhão da PM. "Na próxima, é cadeia, hein, cidadão!"', buttons: [['Entendi', () => closeDialog()]] });
};
/* ============================ CELULAR, PROFISSÕES, APP DE MOTORISTA E RACHA ============================ */
const PASSAGEIROS = ['Dona Cida', 'Seu Jorge', 'Thaís', 'Juninho', 'Pastor Elias', 'Dona Penha', 'Marcão', 'Bia da Farmácia', 'Tio Zezinho', 'Kelly', 'Rafa do Bloco', 'Vó Lurdes', 'Diego Entregador', 'Professora Solange', 'Painho Raimundo', 'Guri Matheus', 'Tonho Mineiro', 'Chicó do Sertão', 'Dona Socorro', 'Mano Wellington'];
const FALAS_EMBARQUE = ['"Boa noite, moço! Pode ir pela avenida que é mais rápido."', '"Liga o ar aí, por favor?"', '"Tô atrasada pro plantão, vai com fé!"', '"Nossa, esse carro é raiz, hein?"', '"Me deixa na porta, que tá escuro."', '"Pode botar um pagodinho no rádio?"', '"Uai, sô, esse trem é rebaixado demais da conta!"', '"Bah, tchê, que frio! Liga o ar quente aí, guri."', '"Oxente, motorista! Tu é ligeiro, hein? Gostei, visse?"', '"Égua, mano, que carro massa!"', '"Ô, meu, vai pela avenida que é mais rápido. Confia."', '"Caraca, mermão, esse som é sinistro!"', '"Pode ir pelo caminho que você achar melhor."', '"Cuidado que eu tô com bolo no colo!"', '"Moço, liga o pisca, pelo amor de Deus."', '"Tô com fome, passa no drive-thru? Brincadeira."', '"Esse carro é seu ou é alugado?"', '"Corre não, que eu enjoo fácil."', '"Boa! Achei que ia demorar mais."', '"Me conta: muito passageiro doido hoje?"'];
const JOB_TYPES = {
  pickup: { name: 'Frete de picape', items: ['Sacos de cimento', 'Mudança pequena', 'Tijolos baianos', 'Geladeira usada', 'Móveis da vó'], mult: 1.35 },
  bau: { name: 'Carga de baú', items: ['Carga de bebidas', 'Caixas de mercadoria', 'Eletrodomésticos', 'Engradados de refrigerante'], mult: 2.2 },
  gas: { name: 'Entrega de gás', items: ['Botijões de gás'], mult: 1.6 },
  tanker: { name: 'Abastecer posto', items: ['Gasolina comum', 'Etanol', 'Diesel S10'], mult: 2.8, fragile: true },
  cacamba: { name: 'Retirar entulho', items: ['Entulho de obra'], mult: 2.0 },
  guincho: { name: 'Reboque', items: ['Carro quebrado de cliente'], mult: 1.9 },
};
// rep: respostas possíveis [[texto, resposta do contato]]; mensagens informativas não têm
// conversas silenciadas: chegam normalmente, mas sem aviso, sem som e sem contar no selo vermelho
function isMuted(from) { return !!(Profile.muted && Profile.muted[from]); }
function unreadCount() { return (Profile.msgs || []).filter((m) => !m.read && !m.me && !isMuted(m.from)).length; }
function addMsg(from, title, body, silent, rep) {
  Profile.msgs = Profile.msgs || [];
  const m = { from, title, body, read: false, t: Math.floor(Profile.time) };
  if (rep) m.rep = rep;
  Profile.msgs.unshift(m);
  if (!silent && !isMuted(from)) { const cfg = phoneCfg(); if (cfg.notif) toast('Nova mensagem: ' + from, (title || body.slice(0, 40)) + ' — aperte Q para abrir o celular.', 'info'); if (cfg.sounds) { AudioSys.tone(1568, 0.08, 'sine', 0.08, 'ui'); AudioSys.tone(2093, 0.12, 'sine', 0.08, 'ui', null, 0.1); } }
  return m;
}
// prévia de localização estilo WhatsApp (mapinha desenhado, sem imagem externa)
const WA_LOC_SVG = '<svg viewBox="0 0 240 110" preserveAspectRatio="xMidYMid slice"><rect width="240" height="110" fill="#e6e1d3"/><path d="M0 70 C60 60 90 85 140 72 S210 50 240 58 L240 110 L0 110Z" fill="#b9d6e6"/><g stroke="#fff" stroke-width="7" fill="none"><path d="M-5 38 H245"/><path d="M70 -5 V115"/><path d="M175 -5 V115"/></g><g stroke="#ffd36b" stroke-width="9" fill="none"><path d="M-5 20 L245 92"/></g><g stroke="#fff" stroke-width="3" fill="none"><path d="M120 -5 V40"/><path d="M20 -5 V40"/></g><rect x="88" y="44" width="22" height="14" fill="#cfd8b8"/><rect x="186" y="12" width="30" height="18" fill="#cfd8b8"/><g transform="translate(120 52)"><ellipse cx="0" cy="14" rx="7" ry="2.5" fill="rgba(0,0,0,0.25)"/><path d="M0 14 C-4 6 -12 0 -12 -8 A12 12 0 0 1 12 -8 C12 0 4 6 0 14Z" fill="#e2412f"/><circle cx="0" cy="-8" r="4.5" fill="#7a1a10"/></g></svg>';
function ensurePhoneData() {
  if (!Profile.msgs) {
    Profile.msgs = [];
    addMsg('Seu Zé (Oficina)', 'Bem-vindo a São Gambiarra!', 'Aqui é o Seu Zé, da oficina. Seu carro tá na garagem.\nTrabalho tem: PegaAí, Fretes e entregas no amarelo.\nBateu? Passa aqui. Boa noite!', true);
  }
  if (Profile.rides === undefined) { Profile.rides = 0; Profile.ratingSum = 0; Profile.jobs = 0; }
  if (!Profile.sosMsg) { Profile.sosMsg = true; addMsg(ZE, 'Socorro 24h', 'Ficou sem gasolina ou quebrou? Me chama aqui que eu vou com o guincho. Custa 15% a mais.', true); }
}
function randomHome(nx, ny, dmin, dmax) {
  const pool = World.homes.filter((h) => { const d = Math.hypot(h.x - nx, h.y - ny); return d > dmin && d < dmax; });
  return pick(pool.length ? pool : World.homes);
}
function routeLen(a, b) { const r = gpsRoute(a.x, a.y, b.x, b.y); return r ? r.len : Math.hypot(a.x - b.x, a.y - b.y) * 1.3; }
function genJob(type) {
  const J = JOB_TYPES[type];
  let pickPt, dest;
  const P = { x: player.x, y: player.y };
  if (type === 'pickup') {
    const s = pick(World.shops.filter((x) => ['mercado', 'paneleiras', 'oficina', 'sitio', 'fazenda'].includes(x.kind)));
    pickPt = { x: s.x, y: s.y, name: s.name }; const h = randomHome(s.x, s.y, 900, 3600); dest = { x: h.x, y: h.y, name: h.name };
  } else if (type === 'bau') {
    const d = World.depots.bau; pickPt = { x: d.x, y: d.y, name: d.name };
    const s = pick(World.shops.filter((x) => ['mercado', 'padaria', 'farmacia', 'lanchonete', 'churrascaria', 'bar', 'moquecaria', 'fazenda', 'sitio'].includes(x.kind)));
    dest = { x: s.x, y: s.y, name: s.name };
  } else if (type === 'gas') {
    const d = World.depots.gas; pickPt = { x: d.x, y: d.y, name: d.name }; const h = randomHome(d.x, d.y, 700, 4000); dest = { x: h.x, y: h.y, name: h.name };
  } else if (type === 'tanker') {
    const d = World.depots.fuel; pickPt = { x: d.x, y: d.y, name: d.name }; const s = pick(World.shops.filter((x) => x.kind === 'posto')); dest = { x: s.x, y: s.y, name: s.name };
  } else if (type === 'cacamba') {
    const o = pick(World.obras); pickPt = { x: o.x, y: o.y, name: o.name }; const d = World.depots.aterro; dest = { x: d.x, y: d.y, name: d.name };
  } else {
    const h = randomHome(P.x, P.y, 500, 2600); pickPt = { x: h.x, y: h.y, name: h.name };
    const s = World.shops.find((x) => x.kind === 'oficina'); dest = { x: s.x, y: s.y, name: s.name };
  }
  const len = routeLen(pickPt, dest) + routeLen(P, pickPt) * 0.3;
  const reward = Math.round((90 + len * 0.08) * J.mult / 5) * 5;
  return { type, item: pick(J.items), pick: pickPt, dest, len, reward, par: len / 190 + 35, fragile: !!J.fragile, hot: false, jobName: J.name, color: pick(CAR_COLORS) };
}
function startJob(job) {
  Act.delivery = Object.assign({}, job, { t: 0, hits: 0, stage: 'pickup', shop: { name: job.pick.name } });
  Act.gpsT = 0;
  AudioSys.chime();
  toast(job.jobName + ' aceito', 'Buscar ' + job.item.toLowerCase() + ' em ' + job.pick.name + '.', 'info');
  frStart(Act.delivery);
}
// ---------- app de motorista ----------
function canDriveRides() { return player && VMODELS[player.car.model].kind !== 'truck'; }
// ---------- racha ----------
function rachaOpen() { const t = Profile.time % 1440; return t >= 22 * 60 || t < 4 * 60 + 30; }
function startRacha(r) {
  if (Profile.money < r.bet) { toast('Sem grana pra aposta', 'O racha custa R$ ' + fmtMoney(r.bet) + '.', 'bad'); AudioSys.error(); return; }
  Profile.money -= r.bet; UI.moneyDelta(-r.bet);
  Act.race = { r, idx: 0, t: 0, count: 3.4, lastBeep: 4, racha: true };
  toast('Racha contra ' + r.rival, 'Aposta R$ ' + fmtMoney(r.bet) + ' · tempo dele: ' + fmtTime(r.rivalTime) + '. Fuja das viaturas!', 'bad');
}
function finishRacha(R) {
  const r = R.r;
  Act.race = null;
  const pos = Recordes.posicao(r, R.t), antes = Recordes.meu(r); Recordes.racha(r, R.t);
  const placar = pos + 'º lugar no placar' + (!antes || R.t < antes ? ' · novo recorde seu' : '');
  if (R.t < r.rivalTime) { AudioSys.chime(); Profile.rachaWins = (Profile.rachaWins || 0) + 1; Desafios.conta('racha'); pay(r.bet * 2, 'Ganhou o racha de ' + r.rival + '! (' + fmtTime(R.t) + ' · ' + placar + ')'); }
  else toast('Perdeu o racha', r.rival + ' chegou antes (' + fmtTime(r.rivalTime) + ' contra ' + fmtTime(R.t) + '). ' + placar + '.', 'bad');
  saveGame();
}
function rachaGhostPos(R) {
  const r = R.r, d = clamp(R.t / r.rivalTime, 0, 1) * r.len;
  let acc = 0;
  for (let i = 1; i < r.all.length; i++) {
    const a = r.all[i - 1], b = r.all[i], L = Math.hypot(b[0] - a[0], b[1] - a[1]);
    if (acc + L >= d) { const k = (d - acc) / L; return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, Math.atan2(b[1] - a[1], b[0] - a[0])]; }
    acc += L;
  }
  const z = r.all[r.all.length - 1]; return [z[0], z[1], 0];
}
// ---------- música do gás ----------
const GasJingle = { t: 0 };
function gasJingle(dt) {
  if (!AudioSys.ok || !player || player.car.job !== 'gas' || !Act.delivery || Act.delivery.stage !== 'deliver') { GasJingle.t = 0; return; }
  GasJingle.t -= dt;
  if (GasJingle.t > 0) return;
  GasJingle.t = 7;
  // "Pour Elise" (domínio público), a musiquinha do caminhão de gás
  const N = [659, 622, 659, 622, 659, 494, 587, 523, 440];
  N.forEach((f, i) => { AudioSys.tone(f, 0.22, 'triangle', 0.05, 'engine', null, i * 0.18); AudioSys.tone(f * 2, 0.12, 'sine', 0.015, 'engine', null, i * 0.18); });
}
// ---------- atualização ----------
function updateJobs(dt) {
  const p = player, sp = p.speed;
  ensurePhoneData();
  // estágio de coleta de fretes
  if (Act.delivery && Act.delivery.stage === 'pickup') {
    const d = Act.delivery;
    if (Math.hypot(d.pick.x - p.x, d.pick.y - p.y) < 75 && sp < 40) {
      d.stage = 'deliver'; d.t = 0; Act.gpsT = 0;
      AudioSys.thud(); AudioSys.tone(660, 0.1, 'triangle', 0.08, 'ui');
      toast('Carregado!', d.item + ' a bordo. Leve até ' + d.dest.name + '.', 'good');
    }
  }
  gasJingle(dt);
  // app de motorista
  if (Act.rideOnline && !Act.ride && !Act.delivery && !Act.race) {
    Act.rideT -= dt / 1.35 * (typeof demandaHora === 'function' ? demandaHora() : 1); // achar passageiro demora 35% mais (e muda com a hora do dia)
    if (Act.rideT <= 0) newRideRequest();
  }
  if (Act.ride) {
    const R = Act.ride;
    R.t += dt;
    if (R.stage === 'pickup' && Math.hypot(R.pick.x - p.x, R.pick.y - p.y) < 82 && sp < 35) {
      Embarque.entra(Embarque.esperando(R), R.pick.x, R.pick.y); // anda até a porta e entra (não some do nada)
      R.stage = 'drive'; R.t = 0; Act.gpsT = 0; AudioSys.thud();
      toast(R.name + ' entrou', rideOnBoard(R), 'info');
    } else if (R.stage === 'drive' && Math.hypot(R.dest.x - p.x, R.dest.y - p.y) < 70 && sp < 35) {
      rideFinish(R);
    }
  }
  // racha: polícia de olho
  if (Act.race && Act.race.racha && Act.race.count <= 0) {
    for (const c of Traffic.cars) {
      if (c.model !== 'police') continue;
      if (Math.hypot(c.x - p.x, c.y - p.y) < 380) {
        Act.race = null;
        const fine = Math.min(300, Math.max(0, Math.floor(Profile.money)));
        Cam.flash = 0.6; AudioSys.siren();
        if (fine) pay(-fine, 'Sujou! A viatura viu o racha. Multa e aposta perdida.'); else toast('Sujou!', 'A viatura viu o racha. Aposta perdida.', 'bad');
        break;
      }
    }
  }
  // convite do racha quando chega a madrugada
  if (rachaOpen() && !Profile.rachaMsg) { Profile.rachaMsg = true; addMsg('Zé do Canecão', 'Racha hoje?', 'E aí, parceiro. Hoje tem racha: arrancada na BR-101, pega na Avenida Cara-Pintada e o racha do Centrão. Aposta na hora, quem ganhar leva o dobro. Abre o app Racha que eu te passo o ponto. Só fica esperto com a viatura, que se ela vir, é multa na certa.', false,
    [['Tô dentro!', 'Fechou! Abre o app Racha que o ponto tá lá. Chega quieto e sem farol alto.'], ['Hoje não, valeu', 'Tranquilo, parceiro. Até a madrugada acaba, se mudar de ideia é só chegar.']]); }
  if (!rachaOpen()) Profile.rachaMsg = false;
}

/* ---------- socorro do Seu Zé: chama pelo zap e ele vem de guincho (15% mais caro que a oficina) ---------- */
const ZE = 'Seu Zé (Oficina)';
const Socorro = { job: null };
// itens do socorro: um serviço só, ou o Kit completo (tudo o que o carro está precisando, montado sozinho)
function socorroItens(kind) {
  const S = zeServicos(1.15, true);
  if (kind === 'kit') return S.filter((i) => i.precisa);
  if (kind === 'pneu') kind = 'tires';
  return S.filter((i) => i.k === kind);
}
function socorroQuote(kind) { return socorroItens(kind).reduce((a, i) => a + i.preco, 0); }
// rota pela mão direita da pista (os pontos do GPS ficam no meio da rua)
function laneShift(pts, off) {
  const out = pts.map((p) => p.slice());
  for (let i = 1; i < pts.length - 1; i++) {
    const a = pts[i - 1], b = pts[i], c = pts[i + 1];
    let dx = (c[0] - a[0]), dy = (c[1] - a[1]); const d = Math.hypot(dx, dy) || 1; dx /= d; dy /= d;
    out[i] = [b[0] - dy * off, b[1] + dx * off];
  }
  return out;
}
// anda pela rota respeitando quem está na frente (carros da IA e você)
function socorroDrive(J, speed, dt) {
  const c = Math.cos(J.a), s = Math.sin(J.a);
  let blocked = false;
  const ahead = (x, y) => { const rx = x - J.x, ry = y - J.y, f = rx * c + ry * s, l = Math.abs(-rx * s + ry * c); return f > 0 && f < 70 && l < 18; };
  for (const o of Traffic.cars) if (ahead(o.x, o.y)) { blocked = true; break; }
  if (J.state === 'leaving' && player && ahead(player.x, player.y)) blocked = true;
  J.v = lerp(J.v || 0, blocked ? 0 : speed, 1 - Math.exp(-3 * dt));
  let step = J.v * dt;
  while (step > 0 && J.ri < J.pts.length) {
    const p = J.pts[J.ri], dx = p[0] - J.x, dy = p[1] - J.y, d = Math.hypot(dx, dy);
    if (d < 0.5) { J.ri++; continue; }
    const m = Math.min(d, step); J.x += dx / d * m; J.y += dy / d * m; step -= m;
    J.a += angDiff(J.a, Math.atan2(dy, dx)) * Math.min(1, dt * 7);
    if (m >= d) J.ri++;
  }
  return J.ri >= J.pts.length;
}
// (0.2.0) o caminhão do Seu Zé é um carro do trânsito de verdade (AICar com rota): anda na faixa dele, respeita sinal,
// espera na fila, não atravessa ninguém e faz as curvas como os outros. Ele segue a rota (navNos) até a rua onde você está
// e encosta perto de você. Se estiver no meio da rua ou no cruzamento quando você mudar de lugar, segue até o próximo
// cruzamento e de lá pega o novo caminho (nunca dá meia-volta no meio da rua).
function socorroAlvo(x, y) { const B = nearestEdge(x, y); return B && B.e ? { e: B.e, s: B.s } : null; }
function socorroMira(car, A) {
  car.rota = { alvoE: A.e, alvoS: A.s, nos: null };
  if (car.state === 'edge' && !car.committed) { car.plan = null; car.chooseNext(); }
}
// onde ele encosta: um pouco antes de você, na rua onde você está (no sentido em que ele chega)
function socorroPara(car) {
  const R = car.rota; if (!R || !R.dirFinal) return;
  car.paraE = R.alvoE; car.paraDir = R.dirFinal;
  const sP = R.dirFinal > 0 ? R.alvoS : R.alvoE.len - R.alvoS;
  car.paraEm = sP - 34;
}
function socorroCarro(J) {
  const ox = J.sx, oy = J.sy; // oficina (se perto) ou uma rua a uns 1,2 km
  const A = nearestEdge(ox, oy); if (!A.e) return null;
  const e = A.e, dir = ((player.x - ox) * e.dx + (player.y - oy) * e.dy) >= 0 ? 1 : -1, sCar = dir > 0 ? A.s : e.len - A.s;
  const car = new AICar(e, dir, sCar, 0, 'guincho');
  car.ze = true; car.color = '#c8302a'; car.mul = 1; car.cruise = Math.min(e.T.speed, car.vmax); car.v = 0; car.hideT = 0; car.simT = 0;
  Traffic.cars.push(car);
  const T = socorroAlvo(player.x, player.y); if (T) socorroMira(car, T);
  return car;
}
function socorroTira(J) { if (J && J.car) { J.car.release(); J.car.dead = true; Traffic.cars = Traffic.cars.filter((c) => c !== J.car); J.car = null; } }
function socorroCall(kind) {
  if (Socorro.job || !player) return;
  if (!zeFiadoGate()) return; // fiado em aberto: sem acertar, ele não vem
  const of = World.shops.find((s) => s.kind === 'oficina');
  let sx, sy;
  if (of && Math.hypot(of.x - player.x, of.y - player.y) < 2600) { sx = of.x; sy = of.y; }
  else { const a = rnd(TAU); const ne = nearestEdge(clamp(player.x + Math.cos(a) * 1300, 100, WORLD_W - 100), clamp(player.y + Math.sin(a) * 1300, 100, WORLD_H - 100)); sx = ne.e.h ? ne.e.a.x + ne.s : ne.e.a.x; sy = ne.e.h ? ne.e.a.y : ne.e.a.y + ne.s; }
  const route = navRota(sx, sy, player.x, player.y, { soRua: true });
  const len0 = route ? route.len : Math.hypot(sx - player.x, sy - player.y);
  const sai = 5; // pega as ferramentas e sai da oficina
  const itens = socorroItens(kind).map((i) => i.k);
  const J = { kind, itens, sx, sy, x: sx, y: sy, a: 0, state: 'coming', t: 0, rt: 2, quote: socorroQuote(kind), sai, car: null };
  Profile.sos = (Profile.sos || 0) + 1;
  Socorro.job = J;
  const eta = Math.max(1, Math.round((sai + len0 / 150) / 20)); // anda no ritmo do trânsito (sinal, fila, curva)
  const what = kind === 'kit' ? 'o kit completo (' + zeLista(itens) + ')' : kind === 'bat' ? 'uma carga na bateria, ela arriou' : kind === 'tires' || kind === 'pneu' ? 'pneus novos, tô no aro' : kind === 'oil' ? 'uma troca de óleo' : kind === 'fix' ? 'um conserto na lataria' : 'gasolina';
  Profile.msgs.unshift({ from: ZE, title: '', body: 'Seu Zé, preciso de ' + what + '. Me socorre aí!', read: true, me: true, t: Math.floor(Profile.time) });
  setTimeout(() => {
    addMsg(ZE, '', 'Tô indo aí com o guincho! Fica parado num lugar seguro, com o pisca ligado. Chego em uns ' + eta + ' min, depende do trânsito. Fica uns R$ ' + fmtMoney(J.quote) + ' (15% a mais que na oficina, por causa do deslocamento).', true);
    if (Screens.current === 'screen-phone' && Phone.chat === ZE) Phone.render();
    phoneTone(1320, 0.06, 0.05);
  }, 1200);
  Act.waypoint = null; Act.gps = null;
}
function socorroCancel() {
  if (!Socorro.job) return;
  socorroTira(Socorro.job); Socorro.job = null;
  Profile.msgs.unshift({ from: ZE, title: '', body: 'Seu Zé, pode cancelar, já me virei.', read: true, me: true, t: Math.floor(Profile.time) });
  setTimeout(() => { addMsg(ZE, '', 'Beleza, dei meia-volta. Qualquer coisa me chama!', true); if (Screens.current === 'screen-phone' && Phone.chat === ZE) Phone.render(); }, 900);
}
Socorro.update = function (dt) {
  const J = this.job; if (!J || !player) return;
  J.t += dt;
  if (J.sai > 0) { J.sai -= dt; return; } // ainda saindo da oficina
  if (!J.car || !J.car.alive) { if (J.state === 'leaving') { this.job = null; return; } J.car = socorroCarro(J); if (!J.car) return; }
  const car = J.car; J.x = car.x; J.y = car.y; J.a = car.a; J.v = car.v;
  const d = Math.hypot(player.x - car.x, player.y - car.y);
  if (J.state === 'coming') {
    car.hold = false;
    // você mudou de lugar: ele mira a nova rua (o caminho novo começa no próximo cruzamento)
    J.rt -= dt;
    if (J.rt <= 0) {
      J.rt = 2; const T = socorroAlvo(player.x, player.y), R = car.rota;
      if (T && (!R || T.e !== R.alvoE || Math.abs(T.s - R.alvoS) > 120)) socorroMira(car, T);
    }
    socorroPara(car);
    const naRua = car.state === 'edge' && car.e === car.paraE && car.dir === car.paraDir;
    if (d < 80 || (naRua && car.v < 4 && d < 230 && (car.paraEm - car.s < 20 || car.blocker === player))) {
      J.state = 'arrived'; J.t = 0; car.hold = true; car.offT = car.off + (car.e.T.lanes.length === 1 ? 8 : 0); // encosta e liga o pisca
      toast('Seu Zé chegou!', 'Fica parado aí que ele já resolve.', 'info'); AudioSys.aiHorn(60, 'caminhao', 0);
    }
  } else if (J.state === 'arrived') {
    car.hold = true; car.blink = 1;
    if (player.speed > 30) { J.t = 0; if (d > 160) { J.state = 'coming'; J.rt = 0; } return; }
    if (J.t > 0.4 && Math.floor(J.t * 2.5) !== Math.floor((J.t - dt) * 2.5)) AudioSys.wrench();
    if (J.t > 3) {
      // serviço completo; o que faltar de dinheiro o Seu Zé anota no fiado (é amigo)
      const itens = socorroItens(J.kind === 'kit' ? 'kit' : J.itens[0]).filter((x) => J.kind !== 'kit' || J.itens.includes(x.k));
      let cost = 0; for (const it of itens) { cost += it.preco; zeAplica(it.k); }
      const what = itens.length ? 'Feito: ' + zeLista(itens) + '.' : 'Tudo em dia.';
      const ch = zeCharge(cost, true);
      AudioSys.chime();
      toast('Socorro do Seu Zé', what + ' Pago R$ ' + fmtMoney(ch.paid) + (ch.owed ? ' · fiado R$ ' + fmtMoney(ch.owed) : ''), 'good');
      const tip = J.itens.includes('bat') && J.itens.length === 1 ? ' Agora não fica parado com o farol aceso não, hein. Bateria não é poste.' : J.itens.includes('tires') && J.itens.length === 1 ? ' Pneu novo, sapato novo! Para de cantar pneu em toda esquina.' : ' Vai com Deus e devagar.';
      addMsg(ZE, '', ch.owed ? (ch.paid ? 'Peguei os R$ ' + fmtMoney(ch.paid) + ' que você tinha e ' : 'Tá liso, né? Tranquilo, ') + 'anotei R$ ' + fmtMoney(ch.owed) + ' no fiado. Amanhã, na virada da noite, eu pego sozinho se tiver dinheiro. Se atrasar, entra jurinho, viu?' + tip : 'Prontinho, R$ ' + fmtMoney(ch.paid) + '.' + tip, true);
      J.kind = 'done'; J.state = 'leaving'; J.t = 0; saveGame();
      // volta para a oficina pelo trânsito, como qualquer carro
      car.hold = false; car.blink = 0; car.paraE = null;
      const of = World.shops.find((s) => s.kind === 'oficina'), T = of ? socorroAlvo(of.x, of.y) : null;
      if (T) socorroMira(car, T); else car.rota = null;
      J.home = !!T;
    }
  } else if (J.state === 'leaving') {
    if (car.rota && car.rota.dirFinal) socorroPara(car);
    const chegou = car.paraE && car.state === 'edge' && car.e === car.paraE && car.v < 3 && car.paraEm - car.s < 25;
    const longe = Math.hypot(car.x - Cam.x, car.y - Cam.y) > 1400 && J.t > 6; // longe de você: considera que já chegou
    if (chegou || longe || !J.home) { socorroTira(J); this.job = null; }
  }
};
function socorroBar(H) {
  const J = Socorro.job;
  if (J) {
    const d = Math.round(Math.hypot(J.x - player.x, J.y - player.y) * 0.09);
    return `<div class="wa-sos"><b>${J.state === 'coming' ? 'Seu Zé está a caminho · ' + (d > 1000 ? (d / 1000).toFixed(1).replace('.', ',') + ' km' : d + ' m') : J.state === 'arrived' ? 'Seu Zé chegou! Fique parado.' : 'Serviço concluído'}</b>${J.state === 'coming' ? '<button data-sos="cancel" class="off">Cancelar</button>' : ''}</div>`;
  }
  // cada serviço com o nome do que é feito, e o Kit completo (o Seu Zé vê sozinho o que falta)
  const S = zeServicos(1.15, true).filter((i) => i.precisa && i.preco >= 8);
  const opts = S.map((i) => [i.k, i.nome, i.preco, true]);
  const kit = S.length > 1 ? ['kit', 'Kit completo', S.reduce((a, i) => a + i.preco, 0), zeLista(S)] : null;
  const sub = fiadoOpen() ? `<span class="wa-fiado">Fiado em aberto: R$ ${fmtMoney(Math.ceil(Profile.fiado.amount))}</span>` : '<span>Ele vem até você · 15% a mais · faz fiado</span>';
  const linha = (o) => `<button class="wa-sos-item" data-sos="${o[0]}"><span>${o[1]}</span><em>R$ ${fmtMoney(o[2])}</em></button>`;
  return `<div class="wa-sos"><div class="wa-sos-h"><b>Chamar o Seu Zé</b>${sub}</div>` +
    (opts.length ? '<div class="wa-sos-lista">' + opts.map(linha).join('') + '</div>' +
      (kit ? `<button class="wa-sos-kit" data-sos="kit"><span><b>Kit completo</b><small>${kit[3]}</small></span><em>R$ ${fmtMoney(kit[2])}</em></button>` : '')
      : '<small class="wa-sos-ok">Seu carro está em dia. Nada para consertar.</small>') + '</div>';
}

/* ---------- APP TEMPORÁRIO DE TRAPAÇAS (para testes) ----------
   Para remover: troque CHEATS_ENABLED para false (o ícone some e nada disso roda). */
const CHEATS_ENABLED = true;
// trapaças: no navegador (o jogo publicado no link) aparecem direto; no app do Windows só depois de digitar GAMBIARRA
function modoDono() { try { return !!navigator.webdriver || !(window.brnd && window.brnd.desktop) || localStorage.getItem('brnd_dono') === '1'; } catch (e) { return false; } }
const Segredo = { buf: '' };
Segredo.tecla = function (code) {
  if (!/^Key[A-Z]$/.test(code)) return;
  this.buf = (this.buf + code.slice(3)).slice(-9);
  if (this.buf === 'GAMBIARRA') {
    this.buf = '';
    let on = false; try { on = localStorage.getItem('brnd_dono') === '1'; localStorage.setItem('brnd_dono', on ? '0' : '1'); } catch (e) {}
    toast(on ? 'Modo dono desligado' : 'Modo dono ligado', on ? 'As trapaças sumiram do celular.' : 'O app Trapaças apareceu no celular.', 'info');
    if (Screens.current === 'screen-phone') Phone.render();
  }
};
const Cheats = { god: false, turbo: false, semCarros: false };
const CHEAT_PLACES = [
  ['Garagem', () => World.home], ['Oficina do Seu Zé', () => World.shops.find((s) => s.kind === 'oficina')], ['Batalhão da PM', () => World.shops.find((s) => s.kind === 'batalhao')],
  ['Centrão', () => ({ x: 1600, y: 1150 })], ['Feio Rosa', () => ({ x: 1150, y: 7350 })], ['Jardim Cara-Pintada', () => ({ x: 3300, y: 7350 })],
  ['BR-101', () => ({ x: 4200, y: 6221 })], ['Terceira Ponte e Meia', () => ({ x: 5000, y: 1500 })], ['Fazenda Muuuito Longe', () => ({ x: 7700, y: 5000 })],
];
function cheatTeleport(t) {
  if (!t) return;
  const ne = nearestEdge(t.x, t.y), e = ne.e;
  const x = e.h ? e.a.x + ne.s : e.a.x + e.T.lanes[0], y = e.h ? e.a.y + e.T.lanes[0] : e.a.y + ne.s;
  player.place(x, y, e.h ? 0 : Math.PI / 2); Cam.x = x; Cam.y = y; Traffic.fill(x, y); Police.units.length = 0; Police.level = 0;
}
function cheatDo(k, v) {
  const ok = (t) => { toast('Trapaça', t, 'info'); AudioSys.tone(1500, 0.06, 'square', 0.05, 'ui'); };
  if (k === 'money') { pay(10000, null); ok('+R$ 10.000'); }
  if (k === 'fix') { const L = carLife(); L.tires = L.oil = L.bat = 100; CarLife.stalled = false; Profile.damage = 0; Profile.zones = { f: 0, r: 0, l: 0, rt: 0, seed: ((Profile.zones && Profile.zones.seed) || 0) + 1 }; Profile.fuel = 100; Profile.dirt = 0; ok('Carro novo e tanque cheio'); }
  if (k === 'cars') { for (const c of CARS) Profile.owned[c.id] = true; ok('Todos os veículos liberados na garagem'); }
  if (k === 'pois') { for (const q of World.pois) if (!Profile.discovered.includes(q.id)) Profile.discovered.push(q.id); ok('Todos os pontos de interesse revelados'); }
  if (k === 'time') { Profile.time = +v; Dia.update(); ok('Relógio: ' + clockStr()); }
  if (k === 'dia') { Profile.dia = (Dia.semana() + 1) % 7; ok('Hoje é ' + DIAS[Profile.dia]); }
  if (k === 'wx') { Settings.weather = v; if (v === 'auto') { Weather.timer = 0; } else { Weather.target = v === 'chuva' ? 0.9 : v === 'garoa' ? 0.35 : 0; if (v === 'garoa') Settings.weather = 'auto', Weather.target = 0.35, Weather.timer = 120; } saveSettings(); ok('Clima: ' + v); }
  if (k === 'police') { const n = +v; if (n === 0) { Police.level = 0; Police.units.length = 0; ok('Polícia liberada'); } else { Police.crime('Trapaça', n, player.x, player.y, true); Police.level = n; ok(n + ' estrela(s)'); } }
  if (k === 'ev') { Events.clear(); let okv = false; for (let i = 0; i < 12 && !okv; i++) okv = Events.spawn(v); Screens.closeAll(); ok(okv ? 'Evento: ' + EV_NAMES[v] : 'Não achei lugar pra esse evento aqui; tente em outra região'); return; }
  if (k === 'wear') { const L = carLife(), n = +v; L.tires = L.oil = L.bat = n; CarLife.warned = {}; if (n > 5) CarLife.stalled = false; ok('Pneus, óleo e bateria em ' + n + '%'); }
  if (k === 'des') { const D = Desafios.d(), id = D.lista[+v]; if (id && !D.feito[id]) { Desafios.cumpre(id); ok('Desafio cumprido: ' + DES_POR_ID[id].txt); } else ok('Esse já foi feito'); }
  if (k === 'desnovo') { const D = Desafios.d(); D.lista = Desafios.sorteia('x' + Math.random()); D.prog = {}; D.feito = {}; D.bonus = false; D.ganho0 = Profile.earned || 0; ok('Três desafios novos'); }
  if (k === 'deszera') { const D = Desafios.d(); D.prog = {}; D.feito = {}; D.bonus = false; D.ganho0 = Profile.earned || 0; ok('Progresso dos desafios zerado'); }
  if (k === 'god') { Cheats.god = !Cheats.god; ok('Modo indestrutível ' + (Cheats.god ? 'ligado' : 'desligado')); }
  if (k === 'tab') { Phone.chTab = v; Phone.render(); return; }
  if (k === 'semCarros') { Cheats.semCarros = !Cheats.semCarros; if (Cheats.semCarros) { for (const c of Traffic.cars) if (!c.ze) c.release(); Traffic.cars = Traffic.cars.filter((c) => c.ze); } ok(Cheats.semCarros ? 'Ruas vazias: sem carros do trânsito' : 'O trânsito voltou'); }
  if (k === 'turbo') { Cheats.turbo = !Cheats.turbo; player.recalc(); ok('Turbo ' + (Cheats.turbo ? 'ligado' : 'desligado')); }
  if (k === 'tp') { const pl = CHEAT_PLACES[+v]; cheatTeleport(pl && pl[1]()); Screens.closeAll(); ok('Teleporte: ' + (pl ? pl[0] : '')); return; }
  if (k === 'tpgps') { if (Act.waypoint) { cheatTeleport(Act.waypoint); Screens.closeAll(); ok('Teleporte para o destino do GPS'); } else ok('Marque um destino no Mapa antes'); return; }
  saveGame(); Phone.render();
}

