  if (!bigMap) bigMap = new MapView(bigCanvas, MapState.full);
  buildMapLegend();
  { const el = document.getElementById('map-region'); if (el && player) el.textContent = (REGIONS[regionKeyAt(player.x, player.y)] || {}).name || ''; }
