      for (const [x, y] of [[L.x0, L.y0], [L.x1, L.y0], [L.x0, L.y1], [L.x1, L.y1], [(L.x0 + L.x1) / 2, L.y0], [(L.x0 + L.x1) / 2, L.y1]]) ferragem(g, x, y);
